import{b as o}from"./chunk-3CI34XGR.js";import{Va as a,bb as r}from"./chunk-U42HPWME.js";var m=[{title:"Respektuj\xEDc\xED p\u0159\xEDstup",text:"Ke ka\u017Ed\xE9mu p\u0159istupujeme s respektem a vyhrazujeme si dostatek \u010Dasu. A\u0165 u\u017E je v\xE1\u0161 v\xFDchoz\xED stav jak\xFDkoliv, \u010Dek\xE1 v\xE1s diskr\xE9tn\xED prost\u0159ed\xED a profesion\xE1ln\xED \u0159e\u0161en\xED bez v\xFD\u010Ditek."},{title:"Modern\xED vybaven\xED",text:"\u0160pi\u010Dkov\xE1 technologie pro v\xE1\u0161 komfort. Vyu\u017E\xEDv\xE1me modern\xED diagnostick\xE9 p\u0159\xEDstroje, kter\xE9 n\xE1m umo\u017E\u0148uj\xED poskytovat tu nejvy\u0161\u0161\xED mo\u017Enou \xFArove\u0148 stomatologick\xE9 p\xE9\u010De."},{title:"Transparentn\xED cen\xEDk",text:"V\u0161echny ceny najdete p\u0159ehledn\u011B na webu. V\u017Edy p\u0159edem v\xEDte, co hrad\xED poji\u0161\u0165ovna a jak\xE1 je va\u0161e p\u0159\xEDpadn\xE1 investice, je\u0161t\u011B ne\u017E usednete do k\u0159esla."}],d=[{name:"Preventivn\xED p\xE9\u010De a hygiena",text:"Pravideln\xE1 prohl\xEDdka a profesion\xE1ln\xED \u010Di\u0161t\u011Bn\xED zub\u016F, kter\xE9 p\u0159edejde v\u011Bt\u0161\xEDm probl\xE9m\u016Fm d\u0159\xEDv, ne\u017E vzniknou. Z\xE1klad, na kter\xE9m stav\xEDme v\u0161echno ostatn\xED."},{name:"O\u0161et\u0159en\xED zubn\xEDho kazu",term:"konzerva\u010Dn\xED stomatologie",text:"Kdy\u017E zub pot\u0159ebuje v\xFDpl\u0148, pou\u017Eijeme b\xEDl\xFD materi\xE1l, kter\xFD splyne s va\u0161\xEDm \xFAsm\u011Bvem. Z\xE1krok bez zbyte\u010Dn\xE9ho \u010Dek\xE1n\xED a s citem pro to, aby v\xE1s nic nebolelo v\xEDc, ne\u017E mus\xED."},{name:"O\u0161et\u0159en\xED\xA0ko\u0159enov\xFDch kan\xE1lk\u016F",term:"endodoncie",text:"Pokud z\xE1n\u011Bt zas\xE1hne a\u017E ke ko\u0159eni zubu, vy\u010Dist\xEDme a o\u0161et\u0159\xEDme kan\xE1lek tak, aby zub z\u016Fstal zachr\xE1n\u011Bn\xFD, kdykoliv je to mo\u017En\xE9."},{name:"P\xE9\u010De o d\xE1sn\u011B",term:"parodontologie",text:"Zdrav\xE9 d\xE1sn\u011B jsou stejn\u011B d\u016Fle\u017Eit\xE9 jako zdrav\xE9 zuby. \u0158e\u0161\xEDme z\xE1n\u011Bt, krv\xE1cen\xED i preventivn\xED p\xE9\u010Di, a\u0165 m\xE1te jistotu, \u017Ee se o v\xE1s star\xE1me komplexn\u011B."},{name:"B\u011Blen\xED zub\u016F",term:"estetick\xE1 stomatologie",text:"\u0160etrn\xE9 profesion\xE1ln\xED b\u011Blen\xED pod dohledem, ne dom\xE1c\xED pokusy naslepo. V\xFDsledek, kter\xFD vydr\u017E\xED, a p\u0159\xEDstup, kter\xFD va\u0161e zuby nepo\u0161kod\xED."},{name:"Korunky a m\u016Fstky",term:"protetika",text:"Kdy\u017E u\u017E zub pot\u0159ebuje v\xEDc ne\u017E v\xFDpl\u0148, nahrad\xEDme po\u0161kozenou nebo chyb\u011Bj\xEDc\xED \u010D\xE1st korunkou nebo m\u016Fstkem, pevn\u011B a funk\u010Dn\u011B a tak, aby to bylo vid\u011Bt co nejm\xE9n\u011B."},{name:"Chirurgie a extrakce",text:"Od jednoduch\xE9ho vytr\u017Een\xED zubu po komplikovan\u011Bj\u0161\xED z\xE1kroky, v\u017Edy s anestezi\xED a klidem, kter\xFD u n\xE1s najdete v ka\u017Ed\xE9 f\xE1zi o\u0161et\u0159en\xED."},{name:"Zubn\xED implant\xE1ty",term:"implantologie",text:"Trval\xE1 n\xE1hrada chyb\u011Bj\xEDc\xEDho zubu, kter\xE1 funguje a vypad\xE1 jako ten v\xE1\u0161 vlastn\xED. Probereme s v\xE1mi, jestli je implant\xE1t pro va\u0161i situaci ta prav\xE1 volba."},{name:"RTG a diagnostika",text:"Digit\xE1ln\xED rentgen n\xE1m pom\u016F\u017Ee vid\u011Bt p\u0159esn\u011B to, co pouh\xFDm okem nejde, rychle, s minim\xE1ln\xED z\xE1t\u011B\u017E\xED a jako sou\u010D\xE1st t\xE9m\u011B\u0159 ka\u017Ed\xE9ho vy\u0161et\u0159en\xED."},{name:"Zubn\xED n\xE1hrady",term:"sn\xEDmateln\xE1 a fixn\xED protetika",text:"Sn\xEDmateln\xE9 i pevn\xE9 n\xE1hrady chyb\u011Bj\xEDc\xEDch zub\u016F, kter\xE9 vr\xE1t\xED \xFAsm\u011Bvu p\u0159irozen\xFD vzhled a \xFAst\u016Fm b\u011B\u017Enou funkci. Od z\xE1kladn\xED varianty po nadstandardn\xED \u0159e\u0161en\xED, v\u017Edy podle toho, co v\xE1m nejl\xEDp vyhovuje."}],l=["Z\xE1kladn\xED v\xFDpl\u0148","Estetick\xE1 v\xFDpl\u0148, mal\xFD rozsah","O\u0161et\u0159en\xED ko\u0159enov\xE9ho kan\xE1lku, 1 kan\xE1lek","Korunka (kovokeramika)"].map(e=>{let n=r.flatMap(t=>t.items).find(t=>t.name===e);if(!n)throw new Error(`Missing preview price: ${e}`);return{name:e,price:n.price||"bez doplatku"}}),k={heading:"Vedouc\xED l\xE9ka\u0159 a zakladatel",text:"MUDr. Konstantinos Papadopoulos vede Dental Academy s jasnou viz\xED: poskytovat modern\xED stomatologickou p\xE9\u010Di, kter\xE1 je nejen vysoce odborn\xE1, ale p\u0159edev\u0161\xEDm lidsk\xE1 a \u0161etrn\xE1. Za jeho prac\xED stoj\xED l\xE9ta praxe a d\u016Fraz na individu\xE1ln\xED p\u0159\xEDstup ke ka\u017Ed\xE9mu pacientovi.",todo:"PLACEHOLDER \u2014 roky praxe, vzd\u011Bl\xE1n\xED, specializace dopln\xED l\xE9ka\u0159 (docs/content.md)."},v=[{name:a.doctor,role:"Zubn\xED l\xE9ka\u0159",bio:"Nikdo by nem\u011Bl m\xEDt strach p\u0159iznat, jak dlouho p\xE9\u010Di odkl\xE1dal. M\xFDm \xFAkolem je to napravit, ne soudit.",photo:o.doctor,todo:"PLACEHOLDER \u2014 cit\xE1t \u010Dek\xE1 na potvrzen\xED l\xE9ka\u0159em. Bio (vzd\u011Bl\xE1n\xED, praxe, jazyky) ve\u0159ejn\u011B nedohledateln\xE9, dopln\xED l\xE9ka\u0159."},{role:"Zdravotn\xED sestra",photo:o.nurse,todo:"PLACEHOLDER \u2014 jm\xE9no, foto a roli dopln\xED klient."}],u=[{title:"P\u0159iv\xEDt\xE1n\xED a rozhovor",text:"Nejd\u0159\xEDv si popov\xEDd\xE1me o tom, co v\xE1s tr\xE1p\xED nebo co byste cht\u011Bli \u0159e\u0161it. Bez sp\u011Bchu, bez odsuzov\xE1n\xED."},{title:"Vy\u0161et\u0159en\xED",text:"Pod\xEDv\xE1me se na stav chrupu, p\u0159\xEDpadn\u011B ud\u011Bl\xE1me RTG, a\u0165 v\xEDme, na \u010Dem jsme."},{title:"Pl\xE1n p\xE9\u010De",text:"Vysv\u011Btl\xEDme, co navrhujeme a pro\u010D, v\u010Detn\u011B orienta\u010Dn\xED ceny, ne\u017E se do \u010Dehokoliv pust\xEDme."},{title:"O\u0161et\u0159en\xED nebo dal\u0161\xED term\xEDn",text:"Podle toho, co je pot\u0159eba. Bu\u010F rovnou, nebo domluv\xEDme dal\u0161\xED n\xE1v\u0161t\u011Bvu."}],c=[{quote:"Kone\u010Dn\u011B jsem p\u0159estala m\xEDt strach chodit k zuba\u0159i. Pan doktor je mil\xFD a klidn\xFD, \u010Dlov\u011Bk se u n\u011Bj c\xEDt\xED v bezpe\u010D\xED, a ordinace je modern\xED a p\u0159\xEDjemn\xE1.",author:"Jana H.",period:"p\u0159ed 7 m\u011Bs\xEDci"},{quote:"Moc p\u011Bkn\xFD p\u0159\xEDstup k m\xE9mu synovi, hezk\xE1 modern\xED ordinace a p\u0159\xEDjemn\xE1 sest\u0159i\u010Dka. Rychlost, kvalita i cena sed\xED.",author:"Jana D.",period:"p\u0159ed m\u011Bs\xEDcem"},{quote:"M\u011Bla jsem velk\xFD strach z \u010Di\u0161t\u011Bn\xED ko\u0159enov\xE9ho kan\xE1lku, ale z\xE1krok prob\u011Bhl \u0161etrn\u011B, bez bolesti a profesion\xE1ln\u011B. S d\u011Btmi m\xE1 pan doktor \xFA\u017Easnou trp\u011Blivost.",author:"Tereza H.",period:"p\u0159ed 7 m\u011Bs\xEDci"},{quote:"Poctiv\xFD a d\u016Fkladn\xFD p\u0159\xEDstup, \u017E\xE1dn\xE9 zbyte\u010Dn\xE9 z\xE1kroky. Ordinace i \u010Dek\xE1rna jsou modern\xED a \u010Dist\xE9.",author:"Luk\xE1\u0161 K.",period:"p\u0159ed 21 hodinami"}];export{m as a,d as b,l as c,k as d,v as e,u as f,c as g};
